class Solution {
    public int uniquePathsWithObstacles(int[][] obstacleGrid) {
        return countFrom(obstacleGrid, 0, 0);
    }

    private int countFrom(int[][] grid, int row, int column) {
        int rows = grid.length;
        int columns = grid[0].length;
        if (row >= rows || column >= columns || grid[row][column] == 1) return 0;
        if (row == rows - 1 && column == columns - 1) return 1;
        return countFrom(grid, row + 1, column) + countFrom(grid, row, column + 1);
    }
}

